// Frozen #39/#76 cycle closure on the exact WS68 source rows. Rust std only.
use std::collections::VecDeque;
const P:i64=1009; const N:i64=1013; const SMALL:usize=8; const LARGE:usize=16; const Q:usize=24; const RHS:usize=25; const C:usize=26; const HUB:usize=16;
#[derive(Clone,Copy,Debug,PartialEq,Eq)] enum Pt{O,A(i64,i64)}
fn m(x:i64,n:i64)->i64{x.rem_euclid(n)}
fn inv(x:i64,n:i64)->i64{let(mut a,mut b,mut u,mut v)=(m(x,n),n,1,0);while b!=0{let t=a/b;(a,b)=(b,a-t*b);(u,v)=(v,u-t*v)}assert_eq!(a,1);m(u,n)}
fn add(a:Pt,b:Pt)->Pt{match(a,b){(Pt::O,x)|(x,Pt::O)=>x,(Pt::A(x,y),Pt::A(u,v))=>{if x==u&&m(y+v,P)==0{return Pt::O}let s=if x==u{m((3*x*x+1)*inv(2*y,P),P)}else{m((v-y)*inv(u-x,P),P)};let xx=m(s*s-x-u,P);Pt::A(xx,m(s*(x-xx)-y,P))}}}
fn mul(mut k:i64,mut p:Pt)->Pt{if k<0{k=-k;p=match p{Pt::O=>p,Pt::A(x,y)=>Pt::A(x,m(-y,P))}}let mut out=Pt::O;while k>0{if k&1!=0{out=add(out,p)}p=add(p,p);k>>=1}out}
fn base()->Vec<Pt>{let mut v=Vec::new();for x in 0..P{for y in 0..P{if m(y*y-x*x*x-x-14,P)==0{v.push(Pt::A(x,y));break}}if v.len()==24{break}}v}
#[derive(Clone)]struct Source{id:usize,a:i64,b:i64,p:Pt,kind:String,i:usize,j:usize,row:[i64;C]}
fn val(line:&str,key:&str)->i64{line.split_whitespace().find_map(|t|t.strip_prefix(key)).unwrap().trim_end_matches(',').parse().unwrap()}
fn sources()->Vec<Source>{let s=include_str!("WS68_NATURAL_PARTIAL.stdout");let lines:Vec<_>=s.lines().filter(|l|l.starts_with("source id=")).collect();assert_eq!(lines.len(),169);let mut out=Vec::new();for l in lines.into_iter().skip(17){let id=val(l,"id=") as usize;let a=val(l,"a=");let b=val(l,"b=");let r=l.split("r=A(").nth(1).unwrap().split(')').next().unwrap();let mut xy=r.split(',');let x=xy.next().unwrap().trim().parse().unwrap();let y=xy.next().unwrap().trim().parse().unwrap();let kind=l.split("kind=").nth(1).unwrap().split_whitespace().next().unwrap().to_string();let i=val(l,"i=") as usize;let j=val(l,"j=") as usize;let mut row=[0;C];row[i]+=1;row[j]+=1;row[Q]=m(-b,N);row[RHS]=a;out.push(Source{id,a,b,p:Pt::A(x,y),kind,i,j,row})}assert_eq!(out.len(),152);out}
#[derive(Default,Clone,Copy)]struct Cost{adds:u64,muls:u64,invs:u64,cell_scans:u64,path_scans:u64,edge_visits:u64}
fn reduce(row:&mut[i64;C],pivot:&[i64;C],col:usize,c:&mut Cost){let z=row[col];if z==0{return}for k in 0..C{row[k]=m(row[k]-z*pivot[k],N);c.adds+=1;c.muls+=1}}
fn normalize(row:&mut[i64;C],col:usize,c:&mut Cost){let z=inv(row[col],N);c.invs+=1;for k in 0..C{row[k]=m(row[k]*z,N);c.muls+=1}}
fn generic(rows:&[Source],c:&mut Cost)->Vec<[i64;C]>{let mut pivots:[Option<[i64;C]>;LARGE]=[None;LARGE];let mut done=Vec::new();for s in rows{let mut x=s.row;let mut placed=false;for j in 0..LARGE{let col=SMALL+j;c.cell_scans+=1;if x[col]==0{continue}if let Some(p)=pivots[j]{reduce(&mut x,&p,col,c)}else{normalize(&mut x,col,c);pivots[j]=Some(x);placed=true;break}}if !placed{assert!(x[SMALL..Q].iter().all(|&v|v==0));done.push(x)}}done}
fn path(u:usize,v:usize,tree:&[Vec<(usize,usize)>],c:&mut Cost)->Option<Vec<usize>>{let mut parent:[Option<(usize,usize)>;17]=[None;17];let mut q=VecDeque::from([u]);parent[u]=Some((u,usize::MAX));while let Some(x)=q.pop_front(){if x==v{break}for &(y,e) in &tree[x]{c.path_scans+=1;if parent[y].is_none(){parent[y]=Some((x,e));q.push_back(y)}}}parent[v]?;let mut edges=Vec::new();let mut x=v;while x!=u{let (prev,e)=parent[x].unwrap();edges.push(e);x=prev}edges.reverse();Some(edges)}
fn endpoints(s:&Source)->Option<(usize,usize)>{match s.kind.as_str(){"Full"=>None,"One"=>Some((HUB,s.j-SMALL)),"Two"=>Some((s.i-SMALL,s.j-SMALL)),_=>panic!("kind")}}
fn cycle(rows:&[Source],c:&mut Cost)->(Vec<[i64;C]>,usize,usize,usize,usize){let mut tree:Vec<Vec<(usize,usize)>>=vec![Vec::new();17];let mut done=Vec::new();let(mut forest,mut closed,mut failed,mut path_edges)=(0,0,0,0);for (id,s) in rows.iter().enumerate(){let Some((u,v))=endpoints(s)else{done.push(s.row);continue};if let Some(edges)=path(u,v,&tree,c){path_edges+=edges.len();let mut pivots:[Option<[i64;C]>;LARGE]=[None;LARGE];for &e in &edges{let mut x=rows[e].row;for j in 0..LARGE{let col=SMALL+j;c.cell_scans+=1;if x[col]==0{continue}if let Some(p)=pivots[j]{reduce(&mut x,&p,col,c)}else{normalize(&mut x,col,c);pivots[j]=Some(x);break}}}let mut x=s.row;for j in 0..LARGE{let col=SMALL+j;c.cell_scans+=1;if x[col]==0{continue}if let Some(p)=pivots[j]{reduce(&mut x,&p,col,c)}}if x[SMALL..Q].iter().all(|&z|z==0){done.push(x);closed+=1}else{failed+=1}}else{tree[u].push((v,id));tree[v].push((u,id));forest+=1}}(done,forest,closed,failed,path_edges)}
fn component(rows:&[Source],c:&mut Cost)->(Vec<[i64;C]>,usize){let mut adj=vec![Vec::new();17];for s in rows{if let Some((u,v))=endpoints(s){adj[u].push(v);adj[v].push(u)}}let mut comp=[usize::MAX;17];let mut groups=0;for start in 0..17{if comp[start]!=usize::MAX{continue}comp[start]=groups;let mut queue=VecDeque::from([start]);while let Some(x)=queue.pop_front(){for &y in &adj[x]{c.edge_visits+=1;if comp[y]==usize::MAX{comp[y]=groups;queue.push_back(y)}}}groups+=1}let mut out:Vec<[i64;C]>=rows.iter().filter(|s|s.kind=="Full").map(|s|s.row).collect();for k in 0..groups{let sub:Vec<Source>=rows.iter().filter(|s|endpoints(s).is_some_and(|(u,_)|comp[u]==k)).cloned().collect();out.extend(generic(&sub,c))}(out,groups)}
fn ranks(rows:&[[i64;C]],c:&mut Cost)->(usize,usize,Option<i64>){let mut a=rows.to_vec();let mut anchor=[0;C];anchor[0]=1;anchor[RHS]=1;a.push(anchor);let mut base=Vec::new();let mut aug=Vec::new();for x in &a{let mut b=[0;C];b[..SMALL].copy_from_slice(&x[..SMALL]);b[RHS]=x[RHS];base.push(b);let mut d=b;d[SMALL]=x[Q];aug.push(d)}let rb=rank(&mut base,SMALL,c);let ra=rank(&mut aug,SMALL+1,c);let mut answer=None;for x in aug{if x[..SMALL].iter().all(|&v|v==0)&&x[SMALL]!=0{let z=m(x[RHS]*inv(x[SMALL],N),N);if let Some(old)=answer{assert_eq!(old,z)}answer=Some(z)}}(rb,ra,answer)}
fn rank(rows:&mut[[i64;C]],cols:usize,c:&mut Cost)->usize{let mut h=0;for col in 0..cols{if h>=rows.len(){break}let mut found=None;for i in h..rows.len(){c.cell_scans+=1;if rows[i][col]!=0{found=Some(i);break}}if let Some(k)=found{rows.swap(h,k);normalize(&mut rows[h],col,c);let p=rows[h];for i in 0..rows.len(){if i!=h{reduce(&mut rows[i],&p,col,c)}}h+=1}}h}
fn check(rows:&[Source],base:&[Pt],g:Pt,q:Pt){let mut kinds=[0;3];for (id,s) in rows.iter().enumerate(){assert_eq!(id,s.id);assert_eq!(add(base[s.i],base[s.j]),s.p);assert_eq!(add(mul(s.a,g),mul(s.b,q)),s.p);assert_eq!(s.row[s.i],if s.i==s.j{2}else{1});match s.kind.as_str(){"Full"=>kinds[0]+=1,"One"=>kinds[1]+=1,"Two"=>kinds[2]+=1,_=>panic!("kind")}}assert_eq!(kinds,[17,68,67]);println!("source_witnesses={} kinds={:?} input_bytes={} curve=F1009:y2=x3+x+14 order=1013",rows.len(),kinds,include_str!("WS68_NATURAL_PARTIAL.stdout").len())}
fn check_complete(label:&str,rows:&[[i64;C]],base:&[Pt],g:Pt,q:Pt){for (i,r) in rows.iter().enumerate(){assert!(r[SMALL..Q].iter().all(|&v|v==0));let mut left=Pt::O;for j in 0..SMALL{left=add(left,mul(r[j],base[j]))}left=add(left,mul(r[Q],q));assert_eq!(left,mul(r[RHS],g),"{label} row {i}")}println!("{label} complete_witnesses={}",rows.len())}
fn old_main(){let base=base();let g=Pt::A(0,425);let q=Pt::A(779,357);assert_eq!(base[0],g);assert_eq!(mul(N,g),Pt::O);let src=sources();check(&src,&base,g,q);let mut cg=Cost::default();let generic=generic(&src,&mut cg);check_complete("generic",&generic,&base,g,q);let mut cc=Cost::default();let(comp,groups)=component(&src,&mut cc);check_complete("component",&comp,&base,g,q);let mut cr=Cost::default();let(ring,forest,closed,failed,path_edges)=cycle(&src,&mut cr);check_complete("cycle",&ring,&base,g,q);let mut rg=Cost::default();let mut rc=Cost::default();let mut rr=Cost::default();let (gb,ga,gd)=ranks(&generic,&mut rg);let(cb,ca,cd)=ranks(&comp,&mut rc);let(rb,ra,rd)=ranks(&ring,&mut rr);for d in [gd,cd,rd].into_iter().flatten(){assert_eq!(mul(*d,g),q)}println!("generic complete={} rank_base={} rank_aug={} target={:?} filter_cost=adds:{} muls:{} invs:{} cells:{} rank_cost=adds:{} muls:{} invs:{} cells:{}",generic.len(),gb,ga,gd,cg.adds,cg.muls,cg.invs,cg.cell_scans,rg.adds,rg.muls,rg.invs,rg.cell_scans);println!("component groups={} complete={} rank_base={} rank_aug={} target={:?} filter_cost=adds:{} muls:{} invs:{} cells:{} edge_visits:{} rank_cost=adds:{} muls:{} invs:{} cells:{}",groups,comp.len(),cb,ca,cd,cc.adds,cc.muls,cc.invs,cc.cell_scans,cc.edge_visits,rc.adds,rc.muls,rc.invs,rc.cell_scans);println!("cycle complete={} rank_base={} rank_aug={} target={:?} tree_edges={} closures={} nonclosing={} path_edges={} filter_cost=adds:{} muls:{} invs:{} cells:{} path_scans:{} rank_cost=adds:{} muls:{} invs:{} cells:{}",ring.len(),rb,ra,rd,forest,closed,failed,path_edges,cr.adds,cr.muls,cr.invs,cr.cell_scans,cr.path_scans,rr.adds,rr.muls,rr.invs,rr.cell_scans);assert_eq!(forest+closed+failed+17,src.len());println!("scope=source_replay_and_filter_only setup_and_candidate_cost_from_WS68_required=true modular_costs_include_dense_row_ops=true point_arithmetic_unpriced=true");}

fn graph(rows:&[[i64;C]])->([[f64;8];8],u64){let mut w=[[0f64;8];8];let mut tests=0;for r in rows{for i in 0..8{for j in i+1..8{tests+=1;if r[i]!=0&&r[j]!=0{w[i][j]+=1.0;w[j][i]+=1.0}}}}(w,tests)}
fn fiedler(w:&[[f64;8];8])->([f64;8],[f64;8],usize,f64){let mut l=[[0f64;8];8];for i in 0..8{let d:f64=w[i].iter().sum();l[i][i]=d;for j in 0..8{if j!=i{l[i][j]=-w[i][j]}}}let original=l;let mut v=[[0f64;8];8];for i in 0..8{v[i][i]=1.0}let mut rotations=0;for _ in 0..500{let(mut p,mut q,mut max)=(0,1,0f64);for i in 0..8{for j in i+1..8{if l[i][j].abs()>max{p=i;q=j;max=l[i][j].abs()}}}if max<1e-11{break}let tau=(l[q][q]-l[p][p])/(2.0*l[p][q]);let t=if tau>=0.0{1.0/(tau+(1.0+tau*tau).sqrt())}else{-1.0/(-tau+(1.0+tau*tau).sqrt())};let c=1.0/(1.0+t*t).sqrt();let s=t*c;let apq=l[p][q];l[p][p]-=t*apq;l[q][q]+=t*apq;l[p][q]=0.0;l[q][p]=0.0;for k in 0..8{if k!=p&&k!=q{let (a,b)=(l[k][p],l[k][q]);l[k][p]=c*a-s*b;l[p][k]=l[k][p];l[k][q]=s*a+c*b;l[q][k]=l[k][q]}let (a,b)=(v[k][p],v[k][q]);v[k][p]=c*a-s*b;v[k][q]=s*a+c*b}rotations+=1}let mut idx:Vec<usize>=(0..8).collect();idx.sort_by(|&i,&j|l[i][i].partial_cmp(&l[j][j]).unwrap());let k=idx[1];let lambda=l[k][k];let mut residual=0f64;for i in 0..8{let z:f64=(0..8).map(|j|original[i][j]*v[j][k]).sum();residual=residual.max((z-lambda*v[i][k]).abs())}assert!(residual<1e-7);let eig=idx.iter().map(|&j|l[j][j]).collect::<Vec<_>>();let mut vec=[0f64;8];for i in 0..8{vec[i]=v[i][k]}let mut eval=[0f64;8];eval.copy_from_slice(&eig);(vec,eval,rotations,residual)}
fn cut(w:&[[f64;8];8],part:&[usize;4],rows:&[[i64;C]])->(u64,usize,usize,f64){let mut in_a=[false;8];for &i in part{in_a[i]=true}let mut edge=0;for i in 0..8{for j in i+1..8{if in_a[i]!=in_a[j]{edge+=w[i][j] as u64}}}let mut crossing=0;let mut target_crossing=0;for r in rows{let a=(0..8).any(|i|in_a[i]&&r[i]!=0);let b=(0..8).any(|i|!in_a[i]&&r[i]!=0);if a&&b{crossing+=1;if r[Q]!=0{target_crossing+=1}}}let va:f64=part.iter().map(|&i|w[i].iter().sum::<f64>()).sum();let vb:f64=(0..8).filter(|i|!in_a[*i]).map(|i|w[i].iter().sum::<f64>()).sum();(edge,crossing,target_crossing,edge as f64/va+edge as f64/vb)}
fn solve(label:&str,order:[usize;8],rows:&[[i64;C]],g:Pt,q:Pt)->Cost{let mut a:Vec<[i64;10]>=rows.iter().map(|r|{let mut x=[0;10];for j in 0..8{x[j]=r[order[j]]}x[8]=r[Q];x[9]=r[RHS];x}).collect();let mut c=Cost::default();let mut h=0;for col in 0..9{let found=(h..a.len()).find(|&i|{c.cell_scans+=1;a[i][col]!=0});if let Some(i)=found{a.swap(h,i);let z=inv(a[h][col],N);c.invs+=1;for j in 0..10{a[h][j]=m(a[h][j]*z,N);c.muls+=1}let pivot=a[h];for i in 0..a.len(){if i!=h&&a[i][col]!=0{let t=a[i][col];for j in 0..10{a[i][j]=m(a[i][j]-t*pivot[j],N);c.adds+=1;c.muls+=1}}}h+=1}}assert_eq!(h,9);let mut log=[0i64;9];for col in 0..9{let row=a.iter().find(|r|r[col]==1&&(0..9).all(|j|j==col||r[j]==0)).unwrap();log[col]=row[9]}for r in rows{let mut z=0;for j in 0..8{z=m(z+r[order[j]]*log[j],N)}z=m(z+r[Q]*log[8],N);assert_eq!(z,r[RHS])}assert_eq!(mul(log[8],g),q);println!("solve label={label} rank={h} target={} adds={} muls={} invs={} pivot_scans={} rows_checked={}",log[8],c.adds,c.muls,c.invs,c.cell_scans,rows.len());c}
fn main(){let b=base();let g=Pt::A(0,425);let q=Pt::A(779,357);assert_eq!(b[0],g);assert_eq!(mul(N,g),Pt::O);let src=sources();check(&src,&b,g,q);let mut fc=Cost::default();let rows=generic(&src,&mut fc);check_complete("all",&rows,&b,g,q);let (w,tests)=graph(&rows);let (f,eigen,rot,resid)=fiedler(&w);let mut sorted:Vec<usize>=(0..8).collect();sorted.sort_by(|&i,&j|f[i].partial_cmp(&f[j]).unwrap().then(i.cmp(&j)));let mut spec=[0usize;4];spec.copy_from_slice(&sorted[..4]);spec.sort();let fixed=[0,1,2,3];let random=[0,2,5,7];let total_weight:u64=(0..8).map(|i|((i+1)..8).map(|j|w[i][j] as u64).sum::<u64>()).sum();println!("graph rows={} vertices=8 pair_tests={} total_edge_weight={} fiedler_eigenvalues={:?} rotations={} max_residual={:.3e} fiedler_vector={:?}",rows.len(),tests,total_weight,eigen,rot,resid,f);for (label,part) in [("spectral",spec),("fixed",fixed),("seeded_control",random)]{let (edge,cross,target_cross,ncut)=cut(&w,&part,&rows);let mut other:Vec<usize>=(0..8).filter(|i|!part.contains(i)).collect();let mut perm=part.to_vec();perm.append(&mut other);let mut order=[0usize;8];order.copy_from_slice(&perm);println!("partition label={label} left={part:?} cross_edge_weight={edge} crossing_rows={cross} crossing_rows_with_target={target_cross} normalized_cut={ncut:.9}");solve(label,order,&rows,g,q)}println!("filter_cost adds={} muls={} invs={} cell_scans={} source_group_witnesses=152 complete_group_witnesses={} claim_boundary=bounded_EFp_spectral_partition_only eigen_setup_not_modular_cost=true",fc.adds,fc.muls,fc.invs,fc.cell_scans,rows.len());}
